import {pageDocuments,economicDocument} from './studio-model.mjs';
import {checks} from './model.mjs';
import {zipFiles} from './zip.js';
import {pageHeight,requiredHeight} from './layout-engine.js';
import {loadExportOptions,normalizeExportOptions,saveExportOptions} from './export-preferences.js';
import {sheetSVG,WIDTH,HEIGHT} from './sheet.mjs';
import {richTextSVG,bindingValue,fontFamilies} from './text-editor.js';
export function rotatedBounds(b){const angle=(b.rotation||0)*Math.PI/180,c=Math.abs(Math.cos(angle)),s=Math.abs(Math.sin(angle)),w=b.w*c+b.h*s,h=b.w*s+b.h*c;return {x:b.x+(b.w-w)/2,y:b.y+(b.h-h)/2,w,h};}
export function measureOverflow(b,d){if(b.type==='rituals'){const height=requiredHeight(b,d);return {height,overflow:height>b.h};}const body=bindingValue(b,d);if(!body||!['text','ability','equipment','profile','ritualPart'].includes(b.type))return null;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),measure=(t,n,f,bold)=>{ctx.font=`${bold?'bold ':''}${n}px ${f}`;return ctx.measureText(t).width;};const offset=b.part==='content'||b.type==='ritualPart'&&!b.showTitle?0:48,result=richTextSVG(body,b,b.w,b.h-offset,measure);return {...result,height:result.height+offset};}
export function preflight(d,{fontAvailable=()=>true}={}){const warnings=[];for(const b of d.blocks){if(!b.visible)continue;const rect=rotatedBounds(b);if(rect.x<0||rect.y<0||rect.x+rect.w>WIDTH||rect.y+rect.h>pageHeight(d))warnings.push({id:b.id,message:'Parte do elemento está fora da página e não será exportada.'});if(['portrait','image'].includes(b.type)&&!(b.type==='portrait'?d.portrait:b.image))warnings.push({id:b.id,message:'Imagem ausente.'});const overflow=measureOverflow(b,d);if(overflow?.overflow)warnings.push({id:b.id,message:b.autoFit!==false?'O texto precisa de ajuste automático para caber.':'Texto ultrapassa a altura do bloco.'});if(b.bindingIssue)warnings.push({id:b.id,message:'Componente sem equivalência: '+b.bindingIssue.label});if(b.type==='ability'&&!d.abilities.some(a=>a.id===b.ref)||b.type==='ritualPart'&&!d.rituals.some(r=>r.id===b.ref))warnings.push({id:b.id,message:'Componente sem informação vinculada.'});const family=b.textStyle?.family;if(family&&!fontAvailable(family))warnings.push({id:b.id,message:'Fonte indisponível: '+family});}return warnings;}
export function rasterSize(width=1920,height=1431){width=Math.max(320,Math.min(8000,Math.round(Number(width)||1920)));const ratio=height/WIDTH;let h=Math.round(width*ratio);if(width*h>40000000){width=Math.max(320,Math.floor(Math.sqrt(40000000/ratio)));h=Math.round(width*ratio);}return {width,height:h};}
// A small, dependency-free PDF writer. The rendered sheet is embedded as a high-quality JPEG.
export function pdfBytes(jpeg,pixelWidth,pixelHeight,{page='A4',orientation='landscape',margin=10}={}){const sizes={A4:[595.276,841.89],A3:[841.89,1190.551],Letter:[612,792],sheet:[720,720*pixelHeight/pixelWidth]};let [w,h]=sizes[page]||sizes.A4;if(orientation==='landscape'&&w<h||orientation==='portrait'&&w>h)[w,h]=[h,w];const m=Math.max(0,Math.min(80,Number(margin)||0))*72/25.4,ratio=Math.min((w-2*m)/pixelWidth,(h-2*m)/pixelHeight),iw=pixelWidth*ratio,ih=pixelHeight*ratio,x=(w-iw)/2,y=(h-ih)/2,enc=new TextEncoder(),chunks=[],offsets=[0];let length=0;const add=x=>{const bytes=typeof x==='string'?enc.encode(x):x;chunks.push(bytes);length+=bytes.length;};const object=(n,body)=>{offsets[n]=length;add(`${n} 0 obj\n`);add(body);add('\nendobj\n');};add('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Sheet 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=length;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${pixelWidth} /Height ${pixelHeight} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');const content=`q ${iw} 0 0 ${ih} ${x} ${y} cm /Sheet Do Q`;object(5,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`);const xref=length;add('xref\n0 6\n0000000000 65535 f \n');for(let n=1;n<=5;n++)add(String(offsets[n]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const output=new Uint8Array(length);let at=0;for(const chunk of chunks){output.set(chunk,at);at+=chunk.length;}return output;}
export async function renderExport(d,skills,cache,imageData,options={}){for(const b of d.blocks)if(b.image)await imageData(b.image);if(d.portrait)await imageData(d.portrait);await document.fonts?.ready;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${pageHeight(d)}" viewBox="0 0 ${WIDTH} ${pageHeight(d)}">${sheetSVG(d,skills,cache,{transparent:!!options.transparent})}</svg>`;return svg;}
export async function rasterize(svg,width=3840){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const match=svg.match(/viewBox="0 0 ([0-9]+) ([0-9]+)"/),size=rasterSize(width,match?Number(match[2]):1431),canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;canvas.getContext('2d').drawImage(image,0,0,size.width,size.height);return canvas;}finally{URL.revokeObjectURL(url);}}
export function installExports(E){let options=loadExportOptions(),economic=false;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));function showPreflight(){const entries=pageDocuments(E.doc),warnings=entries.flatMap((d,pageIndex)=>preflight(d,{fontAvailable:f=>fontFamilies.includes(f)||[...document.fonts].some(face=>face.family===f&&face.status==='loaded')}).map(w=>({...w,pageIndex,category:/fora da página|altura|ajuste automático|Fonte/.test(w.message)?'Diagramação':'Conteúdo'})));checks(E.doc).forEach((r,i)=>{if(!r.ok){const type=['skills','attributes','resource'][i];let pageIndex=entries.findIndex(d=>d.blocks.some(b=>b.type===type));if(pageIndex<0)pageIndex=0;warnings.push({id:entries[pageIndex].blocks.find(b=>b.type===type)?.id,pageIndex,category:'Regras',message:r.text});}});E.modal('Conferência da ficha',`<p class="subtle">${warnings.length?warnings.length+' aviso(s). Você pode exportar mesmo assim.':'Nenhum problema encontrado.'}</p>${['Conteúdo','Regras','Diagramação'].map(category=>`<details class="studio-section" open><summary>${category} · ${warnings.filter(w=>w.category===category).length}</summary>${warnings.filter(w=>w.category===category).map(w=>`<div class="version-item">Página ${w.pageIndex+1} · ${esc(w.message)} <button data-locate="${w.id||''}" data-locate-page="${w.pageIndex}">${w.id?'Selecionar bloco':'Abrir página'}</button></div>`).join('')}</details>`).join('')}`,`<button data-action="close-modal" class="primary">Concluir</button>`);document.querySelectorAll('[data-locate]').forEach(el=>el.onclick=async()=>{E.closeModal();if(E.doc.pages){const {switchPage}=await import('./studio-model.mjs');E.change(()=>switchPage(E.doc,E.doc.pages[Number(el.dataset.locatePage)].id),true,true);}if(el.dataset.locate)E.select(el.dataset.locate,true,false,true);});}

 function showExportOptions(){E.modal('Exportação de alta qualidade',`<div class="pro-panel"><div class="export-presets"><button data-export-preset="image">Enviar como imagem</button><button data-export-preset="print">Imprimir em A4</button><button data-export-preset="portable">Continuar editando em outro dispositivo</button></div><label><input id="economicExport" type="checkbox" ${economic?'checked':''}> Impressão econômica: fundo claro e sem textura</label><p class="subtle">Todos os formatos incluem as páginas da ficha. Imagens e SVG com várias páginas são entregues em ZIP; PDF reúne as páginas em um arquivo. JSON inclui todos os dados para continuar editando.</p><p class="subtle">PSD contém camadas gráficas e camadas tipográficas nativas para os textos SVG. Fontes ausentes no Photoshop podem ser substituídas. O projeto JSON continua sendo a fonte original para editar os dados. Arquivos PSD com várias páginas são entregues em ZIP.</p><p class="subtle">PNG e PDF usam a mesma composição do SVG. PDF vetorial mantém textos e formas selecionáveis; retratos, textura e efeitos especiais permanecem imagens. Fontes padrão usam equivalentes PDF. O modo Imagem preserva a renderização do navegador.</p><label>Resolução<select id="exportResolution"><option value="1920" ${options.resolution==='1920'?'selected':''}>Padrão · 1920 px</option><option value="3840" ${options.resolution==='3840'?'selected':''}>Alta · 3840 px</option><option value="custom" ${options.resolution==='custom'?'selected':''}>Personalizada</option></select></label><label>Largura personalizada (320–8000 px)<input id="exportWidth" type="number" min="320" max="8000" value="${options.width}"></label><label><input id="exportTransparent" type="checkbox" ${options.transparent?'checked':''}> Fundo transparente (PNG e SVG)</label><div class="compact-grid"><label>Modo PDF<select id="pdfMode"><option value="vector" ${options.pdfMode==='vector'?'selected':''}>Vetorial — texto selecionável</option><option value="image" ${options.pdfMode==='image'?'selected':''}>Imagem — aparência do navegador</option></select></label><label>Papel PDF<select id="pdfPage">${['A4','A3','Letter','sheet'].map(k=>`<option value="${k}" ${options.page===k?'selected':''}>${k==='sheet'?'Tamanho da ficha':k}</option>`).join('')}</select></label><label>Orientação<select id="pdfOrientation"><option value="landscape" ${options.orientation==='landscape'?'selected':''}>Paisagem</option><option value="portrait" ${options.orientation==='portrait'?'selected':''}>Retrato</option></select></label><label>Margens (mm)<input id="pdfMargin" type="number" value="${options.margin}" min="0" max="80"></label></div><div class="pro-toolbar"><button id="preflightExport">Conferir ficha</button>${['png','svg','pdf','psd','json'].map(t=>`<button class="pro-button" data-final-export="${t}">${t.toUpperCase()}</button>`).join('')}</div></div>`,`<button data-action="close-modal" class="quiet">Fechar</button>`);const readOptions=()=>{economic=$('#economicExport').checked;options=normalizeExportOptions({width:$('#exportResolution').value==='custom'?Number($('#exportWidth').value):Number($('#exportResolution').value),resolution:$('#exportResolution').value,transparent:$('#exportTransparent').checked,page:$('#pdfPage').value,orientation:$('#pdfOrientation').value,margin:Number($('#pdfMargin').value),pdfMode:$('#pdfMode').value});try{saveExportOptions(options);}catch{E.toast('Não foi possível guardar as preferências de exportação.');}};for(const id of ['exportResolution','exportWidth','exportTransparent','pdfPage','pdfOrientation','pdfMargin','pdfMode'])$('#'+id).addEventListener('input',readOptions);$('#economicExport').onchange=readOptions;document.querySelectorAll('[data-export-preset]').forEach(el=>el.onclick=()=>{const preset=el.dataset.exportPreset;if(preset==='portable'){exportDoc('json');return;}if(preset==='print'){$('#pdfPage').value='A4';$('#pdfOrientation').value='landscape';$('#pdfMargin').value='10';readOptions();exportDoc('pdf');}else{$('#exportResolution').value='3840';readOptions();exportDoc('png');}});$('#preflightExport').onclick=showPreflight;document.querySelectorAll('[data-final-export]').forEach(el=>el.onclick=()=>{readOptions();exportDoc(el.dataset.finalExport);});}


 const filename=d=>(d.name||'ficha').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').toLowerCase();
 async function portableDocument(d){const portable=structuredClone(d);portable.schemaVersion=2;portable.portrait=await E.imageData(portable.portrait);for(const b of [...portable.blocks,...(portable.pages||[]).flatMap(p=>p.blocks)])if(b.image)b.image=await E.imageData(b.image);return portable;}
 async function exportDocuments(documents,type,name){const entries=documents.flatMap((d,docIndex)=>pageDocuments(d).map((p,i)=>({doc:economic?economicDocument(p):p,name:String(docIndex+1).padStart(2,'0')+'-'+filename(d)+'-'+String(i+1).padStart(2,'0')})));if(entries.length>80)throw Error('Exporte no máximo 80 páginas por lote.');const files=[];let pdf=null,notes=[];for(let i=0;i<entries.length;i++){E.toast('Preparando página '+(i+1)+' de '+entries.length+'…');const entry=entries[i],svg=await renderExport(entry.doc,E.source.skills,E.imageCache,E.imageData,{...options,transparent:type==='pdf'?false:options.transparent});if(type==='pdf'){if(options.pdfMode==='vector'){const {vectorPdf}=await import('./vector-pdf.js');const result=await vectorPdf(svg,entry.doc,options,pdf);pdf=result.pdf;notes.push(...result.notes);}else{const {jsPDF}=await import('./vendor/vector-pdf.js'),{pdfPageDimensions}=await import('./vector-pdf.js'),{w,h}=pdfPageDimensions(options,pageHeight(entry.doc));if(!pdf)pdf=new jsPDF({unit:'pt',format:[w,h],orientation:w>h?'landscape':'portrait'});else pdf.addPage([w,h],w>h?'landscape':'portrait');const canvas=await rasterize(svg,options.width),m=options.margin*72/25.4,ratio=Math.min((w-m*2)/canvas.width,(h-m*2)/canvas.height);pdf.addImage(canvas.toDataURL('image/jpeg',.98),'JPEG',(w-canvas.width*ratio)/2,(h-canvas.height*ratio)/2,canvas.width*ratio,canvas.height*ratio);}}else if(type==='psd'){const {exportPSD}=await import('./psd.js');const blob=await exportPSD(svg,entry.doc,entry.doc.blocks,options.width,{onProgress:(current,total)=>E.toast(`Camada ${current} de ${total} · página ${i+1}`)});files.push({name:entry.name+'.psd',data:new Uint8Array(await blob.arrayBuffer())});}else if(type==='svg'){files.push({name:entry.name+'.svg',data:new TextEncoder().encode(svg)});}else{const canvas=await rasterize(svg,options.width),blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('Não foi possível gerar a imagem.');files.push({name:entry.name+'.png',data:new Uint8Array(await blob.arrayBuffer())});}}
 if(pdf)E.download(new Blob([pdf.output('arraybuffer')],{type:'application/pdf'}),name+'.pdf');else if(files.length===1)E.download(new Blob([files[0].data],{type:type==='svg'?'image/svg+xml':type==='psd'?'image/vnd.adobe.photoshop':'image/png'}),name+'.'+type);else E.download(zipFiles(files),name+'.zip');E.toast('Exportado: '+entries.length+' página(s).'+(notes.length?' Efeitos especiais preservados como imagem.':''));}
 async function exportDoc(type,confirmed=false){$('#exportMenu').hidden=true;document.body.classList.add('busy');try{await E.save();const name=filename(E.doc);if(type!=='json'&&!confirmed){const over=pageDocuments(E.doc).flatMap(d=>preflight(d).filter(w=>/fora da página|altura do bloco/.test(w.message)));if(over.length){E.modal('Conteúdo precisa de revisão',`<p>${over.length} aviso(s) de conteúdo fora dos limites. O PDF ou a imagem podem ficar incompletos. Expanda os blocos ou continue em outra página.</p><button id="reviewBeforeExport">Conferir e localizar</button><button id="continueExportAnyway">Exportar mesmo assim</button>`,'<button data-action="close-modal">Voltar à ficha</button>');$('#reviewBeforeExport').onclick=showPreflight;$('#continueExportAnyway').onclick=()=>{E.closeModal();exportDoc(type,true);};return;}}if(type==='json'){E.download(new Blob([JSON.stringify(await portableDocument(E.doc),null,2)],{type:'application/json'}),name+'.catastrophe.json');E.toast('Backup completo exportado, incluindo todas as páginas.');return;}await exportDocuments([E.doc],type==='print'?'pdf':type,name);}catch(err){E.toast('Erro ao exportar: '+err.message);}finally{document.body.classList.remove('busy');}}
 function showBatchExport(){const docs=E.docs;E.modal('Exportar grupo de fichas',`<div class="pro-panel"><p class="subtle">Seleciona fichas salvas neste navegador. Todas as páginas são incluídas. Imagens individuais são entregues em um ZIP; PDF reúne o grupo em um arquivo. Até 80 páginas por lote.</p>${docs.map(d=>`<label><input type="checkbox" data-batch-id="${d.id}" ${d.id===E.doc.id?'checked':''}> ${esc(d.name)} · ${d.pages?.length||1} página(s) · ${pageDocuments(d).reduce((n,p)=>n+preflight(p).length,0)} aviso(s) de conteúdo/diagramação</label>`).join('')}<label>Formato<select id="batchFormat"><option value="png">Imagens PNG individuais (ZIP)</option><option value="pdf">PDF do grupo</option></select></label><label><input id="batchEconomic" type="checkbox"> Impressão econômica</label><button id="confirmBatch" class="primary">Exportar selecionadas</button><p class="subtle">O PDF usa as últimas opções de papel, orientação e margens do diálogo Exportar.</p></div>`,'<button data-action="close-modal">Fechar</button>');$('#confirmBatch').onclick=async()=>{const ids=[...document.querySelectorAll('[data-batch-id]:checked')].map(el=>el.dataset.batchId);if(!ids.length){E.toast('Selecione ao menos uma ficha.');return;}const type=$('#batchFormat').value,old=economic;economic=$('#batchEconomic').checked;$('#confirmBatch').disabled=true;try{await E.save();await exportDocuments(E.docs.filter(d=>ids.includes(d.id)),type,'catastrophe-grupo');E.closeModal();}catch(err){E.toast('Erro ao exportar: '+err.message);$('#confirmBatch').disabled=false;}finally{economic=old;}};}
 return {exportDoc,showPreflight,showExportOptions,showBatchExport};}
